content.referenceSolution:
function tagWithSymbol(obj, tagName, value) {
  const sym = Symbol.for(tagName);
  return { ...obj, [sym]: value };
}
function readTag(obj, tagName) {
  return obj[Symbol.for(tagName)];
}
function demoTagRead() {
  const o = tagWithSymbol({ id: 1 }, 'meta.kind', 'user');
  return readTag(o, 'meta.kind');
}

