content.referenceSolution:
function readDoubledX(obj) {
  const p = new Proxy(obj, {
    get(target, prop, receiver) {
      if (prop === 'x') return target.x * 2;
      return Reflect.get(target, prop, receiver);
    },
  });
  return p.x;
}
function demoDoubleProxy() {
  return readDoubledX({ x: 7, y: 1 });
}
